import {SAMPLE,DEFAULT_SETTINGS,STATUSES,SIZES,ANGLES,MOVEMENTS,uid,parseScript,promptFor,aiInstruction,toCSV,toMarkdown,videoPromptFor,toVideoText,migrateProject,orderedShots,promptContext,referenceRequirements,parseCSV,exportProject,FOCAL_LENGTHS,DEPTHS,negativePromptFor,promptHints} from './engine.mjs';
import {icon,esc} from './ui-icons.mjs';
import {readScriptFile} from './word-import.mjs';
const KEY='shotflow.project.v1';
const starter=()=>migrateProject({version:1,title:'雨停之前',script:SAMPLE,settings:{...DEFAULT_SETTINGS},shots:parseScript(SAMPLE),isDemo:true});
let state=starter(),storageOK=true,loadError='';
try{const raw=localStorage.getItem(KEY);if(raw)state=migrateProject(JSON.parse(raw));}catch{storageOK=false;loadError='旧项目无法读取，原始存档仍保留，请先导出原始存档。';}
let activeRefinementIds=[];
let panel='script',view='cards',filter='all',episodeFilter='all',query='',statusFilter='all',history=null,fileMode='script',timer,drag=null;
const collapsed=new Set(),app=document.querySelector('#app'),modal=document.querySelector('#modal');
const opts=(values,selected)=>values.map(v=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(v)}</option>`).join('');
const shots=()=>orderedShots(state),ctx=()=>promptContext(state),lang=()=>state.settings.promptLanguage||'zh';
const imagePrompt=s=>promptFor(s,ctx(),lang()),videoPrompt=s=>videoPromptFor(s,ctx(),lang()),negativePrompt=s=>negativePromptFor(s,ctx(),lang());
const getShot=id=>shots().find(s=>s.id===id),getScene=id=>state.scenes.find(s=>s.id===id),getEpisode=id=>state.episodes.find(e=>e.id===id);
const seconds=n=>`${String(Math.floor(Math.round(n)/60)).padStart(2,'0')}:${String(Math.round(n)%60).padStart(2,'0')}`;
const duration=ss=>ss.reduce((a,s)=>a+Number(s.duration||0),0);
const number=s=>s.isIntro?'片头':String(shots().indexOf(s)+1).padStart(2,'0');
const safeImage=s=>typeof s==='string'&&/^data:image\/(?:png|jpeg|webp);base64,[a-z0-9+/=]+$/i.test(s)?s:'';
const input=(label,name,value,attrs='')=>`<label>${label}<input name="${esc(name)}" value="${esc(value)}" ${attrs}></label>`;
const area=(label,name,value,rows=2,attrs='')=>`<label>${label}<textarea name="${esc(name)}" rows="${rows}" ${attrs}>${esc(value)}</textarea></label>`;
const select=(label,name,values,value,attrs='')=>`<label>${label}<select name="${esc(name)}" ${attrs}>${opts([...new Set([...values,value].filter(v=>v!==undefined))],value)}</select></label>`;
function save(){if(loadError)return;try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}saveStatus();}
function saveStatus(){const el=document.querySelector('#save-status');if(el){el.classList.toggle('error',!storageOK);el.innerHTML=`<span class="status-dot"></span>${storageOK?'已保存在此浏览器':'保存未完成，请导出备份'}`;}}
function snapshot(){history=JSON.stringify(state);}
function commit(message='已保存'){save();render();if(message)toast(message);}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>el.classList.remove('show'),3500);}
function showModal(title,content,cls=''){modal.className=cls;modal.innerHTML=`<div class="modal-head"><div><span class="eyebrow">SHOTFLOW STUDIO</span><h2 id="modal-title">${title}</h2></div><button class="icon-button" data-action="close" aria-label="关闭">${icon('close')}</button></div><div class="modal-body">${content}</div>`;if(!modal.open)modal.showModal();}
function confirmAction(title,message,callback){showModal(title,`<p class="confirm-message">${esc(message)}</p><div class="modal-footer"><button class="button" data-action="close">取消</button><button class="button primary" id="confirm-action">确认继续</button></div>`);document.querySelector('#confirm-action').onclick=()=>{modal.close();callback();};}
async function copy(text,message='已复制'){try{await navigator.clipboard.writeText(text);toast(message);}catch{showModal('复制内容',`<p class="muted">选中下方内容后复制。</p><textarea class="copy-fallback" readonly>${esc(text)}</textarea>`);modal.querySelector('textarea').select();}}
function download(name,content,type='text/plain;charset=utf-8'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500);toast('已开始下载');}
const filename=()=>state.title.replace(/[\\/:*?"<>|]/g,'_')||'分镜项目';
function resetFilters(){filter='all';episodeFilter='all';query='';statusFilter='all';}
function render(){app.innerHTML=`<header class="topbar"><a class="brand" href="#" aria-label="镜序工作台"><span class="brand-mark"><i></i><i></i></span><b>镜序</b><span class="brand-en">SHOTFLOW</span><span class="beta">STUDIO</span></a><div class="top-project">${icon('folder')}<span>我的创作</span><span class="slash">/</span><button class="project-title" data-panel="settings">${esc(state.title)} ${icon('down')}</button></div><div class="top-actions"><span id="save-status" class="save-status"></span><button class="icon-button" data-action="help" title="使用指南" aria-label="使用指南">${icon('help')}</button><button class="button primary export-top" data-action="export">${icon('download')}<span>导出分镜</span></button></div></header><div class="workspace"><nav class="rail" aria-label="工作区导航">${[['script','script','剧本'],['board','board','分镜'],['cast','users','角色库'],['episodes','folder','集数'],['settings','sliders','设置']].map(([p,i,l])=>`<button data-panel="${p}" class="rail-button ${panel===p?'active':''}">${icon(i)}<span>${l}</span></button>`).join('')}<div class="rail-bottom"><button class="rail-button" data-action="help">${icon('help')}<span>指南</span></button><span class="avatar">镜</span></div></nav><aside class="editor-panel" aria-label="项目编辑区">${renderPanel()}</aside><main id="board" tabindex="-1">${panel==='cast'?renderLibrary():renderWorkspace()}</main></div>`;saveStatus();if(panel!=='cast')renderBoard();if(loadError)toast(loadError);}
const heading=(title,step,subtitle)=>`<div class="panel-heading"><h2>${title}</h2><span class="step-number">${step}</span></div><p class="panel-intro">${subtitle}</p>`;
function renderPanel(){
 if(panel==='settings')return heading('项目设置','PROJECT','统一每个镜头的视觉基调。')+`<div class="project-form">${input('项目名','title',state.title,'data-project="title" maxlength="100"')}${select('默认画幅','ratio',['9:16','16:9'],state.settings.ratio,'data-setting="ratio"')}${area('统一画风前缀 · 中文','stylePrefix',state.settings.stylePrefix,4,'data-setting="stylePrefix"')}${area('统一画风前缀 · English','stylePrefixEn',state.settings.stylePrefixEn,3,'data-setting="stylePrefixEn"')}${area('通用排除元素 · 中文','negative',state.settings.negative,3,'data-setting="negative"')}${area('通用排除元素 · English','negativeEn',state.settings.negativeEn,3,'data-setting="negativeEn"')}${area('补充色彩与光线','tone',state.settings.tone,2,'data-setting="tone"')}<p class="field-help">自动提示词随设定更新，手工改写的中英文提示词分别保留。</p><div class="section-caption">${icon('sliders')} 空间与光线预设</div><div class="space-list">${state.spaces.map(s=>`<div class="space-preset"><b>${esc(s.name)}</b><p>${esc(s.descriptionZh)}</p><button class="text-button" data-action="edit-space" data-id="${esc(s.id)}">编辑预设</button></div>`).join('')}</div><button class="button full" data-action="add-space">${icon('plus')} 自定义空间</button></div>`;
 if(panel==='episodes'||panel==='board')return heading('集数与场景','OUTLINE','按集统筹节奏，逐场打磨镜头。')+`<div class="episode-navigation">${state.episodes.map(ep=>{const ss=shots().filter(s=>s.episodeId===ep.id);return `<div class="episode-item"><button data-action="filter-episode" data-id="${esc(ep.id)}"><b>${esc(ep.name)}</b><small>${ss.length} 镜 · ${seconds(duration(ss))}</small></button><button class="icon-button" data-action="edit-episode" data-id="${esc(ep.id)}" aria-label="编辑 ${esc(ep.name)}">${icon('edit')}</button></div>${state.scenes.filter(s=>s.episodeId===ep.id).map(sc=>`<button class="scene-item" data-action="filter-scene" data-id="${esc(sc.id)}"><span>${esc(sc.number)} · ${esc(sc.name)}</span><small>${state.shots.filter(s=>s.sceneId===sc.id).length} 镜</small></button>`).join('')}`;}).join('')}</div><button class="button full" data-action="add-episode">${icon('plus')} 新增集</button><button class="button full" data-action="add-scene">${icon('plus')} 新增场景</button><div class="panel-note">${icon('folder')}<div><b>三级顺序，自由调整</b><p>拖动集、场或镜头左侧的手柄调整顺序。也可在编辑窗口中使用上移、下移。</p></div></div>`;
 if(panel==='cast')return heading('角色库','CAST','让每一个镜头，都认得同一个人。')+`<div class="panel-note">${icon('users')}<div><b>${state.characters.length} 位角色</b><p>管理外观、定妆照和代表色，在每个镜头多选同框人物。AI 角色可以参考多位主人。</p></div></div><p class="field-help">定妆照会压缩后保存在当前浏览器，并随 JSON 项目备份导出。提示词会列出需要上传到生成工具的参考图。</p><button class="button primary full" data-action="add-character">${icon('plus')} 新建角色</button><button class="button full" data-panel="settings">${icon('sliders')} 项目视觉设置</button>`;
 return heading('剧本与设置','01 / SCRIPT','一个好故事，是所有镜头的起点。')+`<div class="script-label-row"><label for="script-input" class="field-label">剧本内容</label><div><button class="text-button" data-action="sample">载入示例</button><button class="text-button" data-action="file">${icon('upload')} 导入</button></div></div><div class="script-container"><textarea id="script-input" aria-label="剧本内容" spellcheck="false" placeholder="粘贴剧本，用第01集和场景01标注层级">${esc(state.script)}</textarea><div class="script-bottom"><span id="char-count">${state.script.length.toLocaleString()} 字符</span><span>WORD / TXT / MD</span></div></div><div class="setting-section"><div class="section-caption">${icon('sliders')} 分镜设置</div><span class="field-label">默认画幅</span><div class="ratio-options">${[['9:16','竖屏'],['16:9','横屏']].map(([r,l])=>`<button class="ratio-button ${state.settings.ratio===r?'active':''}" data-ratio="${r}"><i class="ratio-shape r${r.replace(':','')}"></i><span>${r}<small>${l}</small></span>${state.settings.ratio===r?icon('check'):''}</button>`).join('')}</div><div class="setting-row"><label for="style-select">视觉风格</label><select id="style-select" data-setting="style">${opts(['电影写实','日系动画','国风绘本','自定义'],state.settings.style)}</select></div><div class="setting-row"><label for="pace-select">镜头节奏</label><select id="pace-select" data-setting="pacing">${opts(['紧凑','标准','舒缓'],state.settings.pacing)}</select></div><div class="setting-row"><label for="density-select">拆分颗粒度</label><select id="density-select" data-setting="density">${opts(['标准拆分','细致拆分'],state.settings.density)}</select></div><button class="cast-shortcut" data-panel="settings">${icon('sliders')}<span>项目设置与空间光线</span>${icon('chevron')}</button><button class="cast-shortcut" data-panel="cast">${icon('users')}<span>角色库 · ${state.characters.length} 位角色</span>${icon('chevron')}</button></div><div class="generate-wrap"><button class="button generate" data-action="generate">${icon('spark')} 拆分为分镜 ${icon('arrow')}</button><p>本地规则初稿 · 支持后续 AI 精修</p></div><div class="mini-guide"><span class="mini-guide-label">DIRECTOR'S NOTE</span><p>一镜一事，让画面有呼吸。<br>先搭骨架，再打磨每一个镜头。</p><span class="mini-guide-line"></span></div>`;
}
function renderWorkspace(){return `<div class="board-heading"><div><div class="eyebrow"><span></span>从文字到镜头 / SCRIPT TO SCREEN</div><h1>${view==='video'?'视频提示词':'分镜工作台'}<span class="workspace-label">WORKSPACE</span></h1><p>从剧本、分镜到视频，让创作逐镜成形。</p></div><div class="stats" id="stats"></div></div><div class="project-strip"><div class="project-summary">${icon('script')}<span>${esc(state.title)}</span><span class="tag">${state.isDemo?'示例项目':'我的剧本'}</span></div><div class="project-config"><span>${esc(state.settings.ratio)}</span><button data-panel="settings">${icon('sliders')} 项目设置</button><button data-action="ai">${icon('spark')} AI 精修 ${icon('arrow')}</button></div></div><div id="progress"></div><div class="board-toolbar"><div class="view-switch" role="group" aria-label="分镜视图">${[['cards','board','镜头卡片'],['table','list','分镜列表'],['video','video','视频提示词']].map(([v,i,l])=>`<button data-view="${v}" class="${view===v?'active':''}" aria-pressed="${view===v}">${icon(i)}<span>${l}</span></button>`).join('')}</div><div class="language-toggle" role="group" aria-label="提示词语言"><button data-language="zh" class="${lang()==='zh'?'active':''}">中</button><button data-language="en" class="${lang()==='en'?'active':''}">EN</button></div><div class="toolbar-filters"><label class="search-box">${icon('search')}<input id="search" aria-label="搜索分镜" placeholder="搜索镜头…" value="${esc(query)}"></label><select id="episode-filter" aria-label="筛选集数"><option value="all">全部集数</option>${state.episodes.map(ep=>`<option value="${esc(ep.id)}" ${episodeFilter===ep.id?'selected':''}>${esc(ep.name)}</option>`).join('')}</select><select id="scene-filter" aria-label="筛选场景"><option value="all">全部场景</option>${state.scenes.map(sc=>`<option value="${esc(sc.id)}" ${filter===sc.id?'selected':''}>${esc(getEpisode(sc.episodeId)?.name)} / ${esc(sc.number)} ${esc(sc.name)}</option>`).join('')}</select><select id="status-filter" aria-label="筛选状态"><option value="all">全部状态</option>${STATUSES.map(st=>`<option ${statusFilter===st?'selected':''}>${st}</option>`).join('')}</select></div><div class="toolbar-buttons"><button class="icon-button" data-action="undo" title="撤销上次操作" aria-label="撤销上次操作" ${history?'':'disabled'}>${icon('undo')}</button><button class="button subtle" data-action="add" aria-label="新增镜头">${icon('plus')}<span>新增镜头</span></button></div></div>${lang()==='en'?'<p class="field-help">英文版使用对应的英文字段；未填写的画面或角色描述会标为待补充，可在编辑窗口完善。</p>':''}${view==='video'?`<div class="video-intro"><div class="video-flow"><span>01 文字分镜</span><span>→</span><strong>02 视频提示词</strong></div><p>补充动作与表情变化后，复制到图生视频工具。</p><div class="video-tools"><label for="video-mode">生成方式</label><select id="video-mode" data-setting="videoMode">${opts(['图生视频','文生视频'],state.settings.videoMode)}</select><button class="button" data-action="copy-all-video">${icon('copy')} 复制全部</button><button class="button" data-action="export-video">${icon('download')} TXT 导出</button></div></div>`:''}<div id="board-content"></div><footer class="board-footer"><span>${icon('lock')}剧本与参考图保存在此浏览器 · 请定期导出项目备份</span><span>镜序 · 让故事逐镜成形</span></footer>`;}
function visible(s){return (episodeFilter==='all'||s.episodeId===episodeFilter)&&(filter==='all'||s.sceneId===filter)&&(statusFilter==='all'||s.status===statusFilter)&&(!query||`${s.scene} ${s.visual} ${s.characters} ${s.dialogue} ${s.overlay} ${s.sound}`.toLowerCase().includes(query.toLowerCase()));}
const handle=(kind,id)=>`<span class="drag-handle" draggable="false" data-drag="${esc(kind)}" data-id="${esc(id)}" title="拖动调整顺序" aria-label="拖动调整顺序">⠿</span>`;
function renderBoard(){const el=document.querySelector('#board-content');if(!el)return;const all=shots();document.querySelector('#stats').innerHTML=`<div><strong>${String(all.length).padStart(2,'0')}</strong><span>镜头</span></div><div><strong>${state.episodes.length}</strong><span>集 / ${state.scenes.length} 场</span></div><div><strong>${seconds(duration(all))}</strong><span>预计时长</span></div>`;const confirmed=all.filter(s=>s.status==='已确认').length,percent=all.length?Math.round(all.reduce((a,s)=>a+Math.max(0,STATUSES.indexOf(s.status)),0)/(all.length*3)*100):0;document.querySelector('#progress').innerHTML=`<div class="progress-summary"><span>整体进度 <b>${percent}%</b> · 已确认 ${confirmed}/${all.length}</span><div class="progress-track" role="progressbar" aria-label="整体制作进度" aria-valuenow="${percent}" aria-valuemin="0" aria-valuemax="100"><span style="width:${percent}%"></span></div>${STATUSES.map(st=>`<button class="status-badge" data-filter-status="${st}">${st} ${all.filter(s=>s.status===st).length}</button>`).join('')}</div>`;el.className='hierarchy';let count=0;el.innerHTML=state.episodes.filter(ep=>episodeFilter==='all'||ep.id===episodeFilter).map(ep=>{const total=all.filter(s=>s.episodeId===ep.id),intro=ep.intro&&all.find(s=>s.id===ep.intro.id),scenes=state.scenes.filter(sc=>sc.episodeId===ep.id&&(filter==='all'||filter===sc.id));if(!total.some(visible)&&(query||statusFilter!=='all'||filter!=='all'))return '';count++;return `<section class="episode-group"><header class="episode-header" data-drop="episode" data-id="${esc(ep.id)}">${handle('episode',ep.id)}<button class="group-toggle" data-action="collapse" data-key="${esc(ep.id)}" aria-expanded="${!collapsed.has(ep.id)}">${icon(collapsed.has(ep.id)?'chevron':'down')}<b>${esc(ep.name)}</b></button><span class="group-summary">${total.length} 镜 · ${seconds(duration(total))}</span><div class="group-actions"><button class="text-button" data-action="edit-episode" data-id="${esc(ep.id)}">${icon('edit')} 集设置 / 片头</button><button class="icon-button" data-action="add-scene" data-episode="${esc(ep.id)}" aria-label="新增场景">${icon('plus')}</button></div></header>${collapsed.has(ep.id)?'':`${intro&&visible(intro)?`<div class="intro-shot"><div class="scene-header"><b>通用片头</b><span class="group-summary">1 镜 · ${seconds(intro.duration)}</span></div><div class="scene-shots ${view==='cards'?'shot-grid':view==='video'?'video-grid':'table-wrap'}">${view==='table'?renderTable([intro]):view==='video'?renderVideoCard(intro):renderCard(intro)}</div></div>`:''}${scenes.map(renderScene).join('')}${scenes.length?'':'<p class="field-help">本集暂无场景，可在右上角新增。</p>'}`}</section>`;}).join('');if(!count)el.innerHTML=`<div class="empty-wrap"><div class="empty">${icon('board')}<h2>${all.length?'没有匹配的镜头':'故事即将开始'}</h2><p>${all.length?'调整集数、场景或状态筛选。':'先导入剧本，或新增一个镜头。'}</p><button class="button" data-action="clear-filters">清除筛选</button></div></div>`;}
function renderScene(sc){const ss=state.shots.filter(s=>s.sceneId===sc.id),shown=ss.filter(visible);if(ss.length&&!shown.length)return '';const space=state.spaces.find(p=>p.id===sc.spaceId);return `<section class="scene-group"><header class="scene-header" data-drop="scene" data-id="${esc(sc.id)}">${handle('scene',sc.id)}<button class="group-toggle" data-action="collapse" data-key="${esc(sc.id)}" aria-expanded="${!collapsed.has(sc.id)}">${icon(collapsed.has(sc.id)?'chevron':'down')}<b>${esc(sc.number)} · ${esc(sc.name)}</b></button><span class="group-summary">${ss.length} 镜 · ${seconds(duration(ss))}${space?' · '+esc(space.name):''}</span><div class="group-actions"><button class="text-button" data-action="copy-scene" data-id="${esc(sc.id)}">${icon('copy')} 本场提示词</button><button class="icon-button" data-action="edit-scene" data-id="${esc(sc.id)}" aria-label="编辑场景">${icon('edit')}</button><button class="icon-button" data-action="add" data-scene="${esc(sc.id)}" aria-label="本场新增镜头">${icon('plus')}</button></div></header>${collapsed.has(sc.id)?'':`<div class="scene-shots ${view==='cards'?'shot-grid':view==='video'?'video-grid':'table-wrap'}">${view==='table'?renderTable(shown):shown.map(view==='video'?renderVideoCard:renderCard).join('')}${ss.length?'':'<p class="field-help">暂无镜头 · 将镜头拖到场景标题，或点击 + 新增。</p>'}</div>`}</section>`;}
const status=s=>`<select class="status-select" data-shot-status="${esc(s.id)}" aria-label="镜头 ${number(s)} 状态">${opts(STATUSES,s.status)}</select>`;
function momentWarning(s){return s.dialogue?.trim()&&!(lang()==='en'?s.frameMomentEn:s.frameMoment)?.trim()?'<p class="moment-warning">请补充说话时的动作和表情</p>':'';}
function promptAdvice(s){return `<div class="prompt-advice">${references(s)}${promptHints(s,ctx(),lang()).map(h=>`<p>${esc(h)}</p>`).join('')}</div>`;}
function videoAdvice(s){return `<div class="prompt-advice">${state.settings.videoMode==='文生视频'?'':'<p>先用本镜的生图结果作为首帧，再粘贴视频提示词。</p>'}${s.dialogue?`<p>对白参考：${esc(s.dialogue)}</p>`:''}${s.sound?`<p>声音制作参考：${esc(s.sound)}</p>`:''}${s.overlay?`<p>后期叠加：${esc(s.overlay)}</p>`:''}</div>`;}
function negativeEditor(s){return `<div class="negative-editor"><label>负面提示词<textarea rows="2" aria-label="镜头 ${number(s)} 负面提示词" data-negative-for="${esc(s.id)}" data-negative-language="${lang()}">${esc(negativePrompt(s))}</textarea></label><div class="group-actions"><button class="text-button" data-action="copy-negative" data-id="${esc(s.id)}">${icon('copy')} 复制负面提示词</button><button class="text-button" data-action="reset-negative" data-id="${esc(s.id)}">恢复项目默认</button></div></div>`;}
function positionFields(ids,positions={},positionsEn={}){return `<div class="position-grid">${state.characters.filter(c=>ids.includes(c.id)).map(c=>`${input(esc(c.name)+'的位置','position:'+c.id,positions[c.id]||'','placeholder="如：画面左侧前景"')}${input(esc(c.name)+' · Position (EN)','positionEn:'+c.id,positionsEn[c.id]||'','placeholder="e.g. left foreground"')}`).join('')}</div><p class="field-help">未指定时按出场角色顺序安排左侧、右侧等位置，可按实际构图修改。</p>`;}
function references(s){const refs=referenceRequirements(s,ctx());return refs.length?`<div class="reference-strip"><small>生成时上传：</small>${refs.map(c=>`<span>${safeImage(c.referenceImage)?`<img class="reference-thumb" src="${c.referenceImage}" alt="${esc(c.name)}定妆照">`:''}${esc(c.name)}${safeImage(c.referenceImage)?'':'（待上传）'}</span>`).join('')}</div>`:'';}
function renderCard(s){return `<article class="shot-card ${s.status==='已确认'?'confirmed':''}" data-id="${esc(s.id)}" data-drop="shot"><div class="shot-card-top">${s.isIntro?'':handle('shot',s.id)}<span class="shot-index">${number(s)}<small>SHOT</small></span>${status(s)}<button class="confirm-button ${s.done?'done':''}" data-action="confirm" data-id="${esc(s.id)}" title="切换确认状态" aria-label="确认镜头 ${number(s)}">${icon('check')}</button></div><button class="shot-canvas" data-action="edit" data-id="${esc(s.id)}" aria-label="编辑镜头 ${number(s)}"><span class="canvas-top"><span>${esc(s.size)} / ${esc(s.angle)}</span><span>${esc(s.ratio||state.settings.ratio)}</span></span><span class="frame-corner tl"></span><span class="frame-corner tr"></span><span class="frame-corner bl"></span><span class="frame-corner br"></span><span class="canvas-number">${number(s)}</span><span class="canvas-copy">${esc(s.frameMoment||s.visual)}</span><span class="canvas-bottom"><span>${esc(s.characters||'环境 / 动作')}</span><span>${icon('clock')}${s.duration}s</span></span></button><div class="shot-body"><div class="shot-tags"><span>${esc(s.size)}</span><span>${esc(s.movement)}</span><span>${esc(state.spaces.find(p=>p.id===(s.spaceId||getScene(s.sceneId)?.spaceId))?.name||'现实世界')}</span></div><div class="dialogue ${s.dialogue?'':'no-dialogue'}"><span class="quote-mark">“</span><p>${esc(s.dialogue||'无对白 · 以画面叙事')}</p></div>${s.overlay?`<p class="overlay-note">后期：${esc(s.overlay)}</p>`:''}${s.sound?`<p class="field-help">♫ ${esc(s.sound)}</p>`:''}${momentWarning(s)}<details class="prompt-details"><summary><span>${icon('spark')} 生图提示词 · ${lang()==='en'?'EN':'中文'}</span>${icon('down')}</summary><p>${esc(imagePrompt(s))}</p>${promptAdvice(s)}${negativeEditor(s)}<button class="text-button" data-action="copy-prompt" data-id="${esc(s.id)}">${icon('copy')} 复制提示词</button></details><div class="video-shortcut"><button class="text-button" data-action="edit-video" data-id="${esc(s.id)}">${icon('video')} 视频动作与提示词</button><button class="icon-button" data-action="copy-video" data-id="${esc(s.id)}" title="复制视频提示词" aria-label="复制视频提示词">${icon('copy')}</button></div><div class="card-actions"><button class="text-button" data-action="edit" data-id="${esc(s.id)}">${icon('edit')} 编辑分镜</button><button class="icon-button" data-action="copy-prompt" data-id="${esc(s.id)}" title="复制生图提示词" aria-label="复制生图提示词">${icon('copy')}</button></div></div></article>`;}
function renderTable(ss){return `<table><thead><tr><th>镜号</th><th>镜头语言 / 空间</th><th>画面 / 人物</th><th>对白 / 后期 / 声音</th><th>时长</th><th>状态 / 操作</th></tr></thead><tbody>${ss.map(s=>`<tr data-drop="shot" data-id="${esc(s.id)}"><td>${s.isIntro?'':handle('shot',s.id)}${number(s)}</td><td>${esc(s.size)} · ${esc(s.angle)}<small>${esc(s.movement)} / ${esc(s.ratio||state.settings.ratio)}</small></td><td><p>${esc(s.frameMoment||s.visual)}</p>${momentWarning(s)}<small>${esc(s.characters)}</small></td><td><p>${esc(s.dialogue||'—')}</p><small>${s.overlay?'后期：'+esc(s.overlay):''}<br>${s.sound?'声音：'+esc(s.sound):''}</small></td><td>${s.duration}s</td><td>${status(s)}<button class="icon-button" data-action="edit" data-id="${esc(s.id)}" aria-label="编辑分镜">${icon('edit')}</button><button class="icon-button" data-action="copy-prompt" data-id="${esc(s.id)}" aria-label="复制生图提示词">${icon('copy')}</button><button class="icon-button" data-action="edit-video" data-id="${esc(s.id)}" aria-label="编辑视频提示词">${icon('video')}</button></td></tr>`).join('')}</tbody></table>`;}
function renderVideoCard(s){return `<article class="video-card" data-drop="shot" data-id="${esc(s.id)}"><header>${s.isIntro?'':handle('shot',s.id)}<div class="video-number">${number(s)}<span>SHOT</span></div><div class="video-card-scene"><b>${esc(s.characters||'环境镜头')}</b><span>${esc(s.size)} · ${esc(s.movement)} · ${s.duration} 秒</span></div>${status(s)}</header><div class="video-source"><span>分镜画面</span><p>${esc(s.visual)}</p></div><div class="video-prompt-preview">${esc(videoPrompt(s))}</div>${videoAdvice(s)}<footer><button class="button" data-action="edit-video" data-id="${esc(s.id)}">${icon('edit')} 编辑视频提示词</button><button class="button primary" data-action="copy-video" data-id="${esc(s.id)}">${icon('copy')} 复制</button></footer></article>`;}

function renderLibrary(){return `<div class="library-page"><div class="library-heading"><div><div class="eyebrow">CHARACTER BIBLE / 角色一致性</div><h1>角色库</h1><p class="muted">用外观、定妆照与代表色，连接故事里的每个人。</p></div><button class="button primary" data-action="add-character">${icon('plus')} 新建角色</button></div><div class="character-grid">${state.characters.map(c=>`<article class="character-card"><div class="character-portrait" style="border-color:${/^#[a-f0-9]{6}$/i.test(c.color)?c.color:'#dbbb7d'}">${safeImage(c.referenceImage)?`<img src="${c.referenceImage}" alt="${esc(c.name)}定妆照">`:`<span>${esc(c.name.slice(0,1))}</span><small>待上传定妆照</small>`}</div><div class="character-info"><h3><i class="color-dot" style="background:${/^#[a-f0-9]{6}$/i.test(c.color)?c.color:'#dbbb7d'}"></i>${esc(c.name)}</h3><span class="status-badge">${esc(c.type)}</span><p>${esc(c.descriptionZh||'尚未填写中文外观')}</p><p class="field-help">${esc(c.descriptionEn||'English appearance pending')}</p>${c.referenceOwnerIds?.length?`<p class="character-meta">参考主人：${c.referenceOwnerIds.map(id=>esc(state.characters.find(x=>x.id===id)?.name||'')).join('、')}</p>`:''}<div class="character-actions"><button class="button" data-action="edit-character" data-id="${esc(c.id)}">${icon('edit')} 编辑角色</button><button class="icon-button danger" data-action="delete-character" data-id="${esc(c.id)}" aria-label="删除角色 ${esc(c.name)}">${icon('trash')}</button></div></div></article>`).join('')||'<div class="empty-library">暂无角色，点击“新建角色”开始。</div>'}</div></div>`;}
function editCharacter(id){const existing=state.characters.find(c=>c.id===id),c=existing||{id:uid(),name:'',type:'真人',descriptionZh:'',descriptionEn:'',referenceImage:'',color:'#dbbb7d',referenceOwnerIds:[]};let image=safeImage(c.referenceImage);showModal(existing?'编辑角色':'新建角色',`<form id="character-form"><div class="edit-row">${input('名字','name',c.name,'required maxlength="60"')}${select('类型','type',['真人','AI','Q版AI'],c.type)}</div>${area('中文外观描述','descriptionZh',c.descriptionZh,3)}${area('英文外观描述','descriptionEn',c.descriptionEn,3)}<div class="edit-row">${input('代表色','color',c.color,'type="color"')}<label>定妆参考图<input id="reference-upload" type="file" accept="image/png,image/jpeg,image/webp"><small class="field-help">自动压缩保存，支持 PNG / JPEG / WebP</small></label></div><div id="reference-preview" class="upload-preview">${image?`<img src="${image}" alt="定妆照预览">`:'尚未上传'}<button class="text-button danger" type="button" id="remove-reference">移除图片</button></div><fieldset class="cast-picker" id="owner-picker"><legend>参考主人 · AI / Q版AI 可多选</legend>${state.characters.filter(x=>x.id!==c.id).map(x=>`<label class="cast-chip"><input type="checkbox" name="owner" value="${esc(x.id)}" ${c.referenceOwnerIds.includes(x.id)?'checked':''}>${esc(x.name)}</label>`).join('')||'<small>先创建主人角色，再关联参考。</small>'}</fieldset><div class="modal-footer"><button type="button" class="button" data-action="close">取消</button><button class="button primary" id="save-character">保存角色</button></div></form>`,'edit-modal');const form=document.querySelector('#character-form'),preview=document.querySelector('#reference-preview'),upload=document.querySelector('#reference-upload');const sync=()=>{document.querySelector('#owner-picker').disabled=form.elements.type.value==='真人';};sync();form.elements.type.onchange=sync;
 upload.onchange=async()=>{const f=upload.files[0];if(!f)return;const button=document.querySelector('#save-character');button.disabled=true;try{image=await compressImage(f);preview.innerHTML=`<img src="${image}" alt="定妆照预览"><button class="text-button danger" type="button" id="remove-reference">移除图片</button>`;wireRemove();}catch(e){toast(e.message);}finally{button.disabled=false;}};
 function wireRemove(){document.querySelector('#remove-reference').onclick=()=>{image='';preview.innerHTML='尚未上传';upload.value='';};}wireRemove();form.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(form)),name=d.name.trim();if(!name){toast('请填写角色名');return;}if(state.characters.some(x=>x.id!==c.id&&x.name===name)){toast('角色名已存在，请使用不同名字');return;}snapshot();Object.assign(c,{name,type:d.type,descriptionZh:d.descriptionZh.trim(),descriptionEn:d.descriptionEn.trim(),color:d.color,referenceImage:image,referenceOwnerIds:d.type==='真人'?[]:new FormData(form).getAll('owner')});if(!existing)state.characters.push(c);syncNames();modal.close();commit('角色已保存');};}
function compressImage(file){return new Promise((resolve,reject)=>{if(file.size>10*1024*1024)return reject(new Error('请选择 10 MB 以内的参考图'));if(!['image/png','image/jpeg','image/webp'].includes(file.type))return reject(new Error('请选择 PNG、JPEG 或 WebP 图片'));const reader=new FileReader();reader.onerror=()=>reject(new Error('图片读取失败'));reader.onload=()=>{const image=new Image();image.onerror=()=>reject(new Error('图片无法读取，请换一张'));image.onload=()=>{const scale=Math.min(1,512/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(image,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',0.8));};image.src=reader.result;};reader.readAsDataURL(file);});}
function syncNames(){for(const s of shots())s.characters=(s.characterIds||[]).map(id=>state.characters.find(c=>c.id===id)?.name).filter(Boolean).join('、');state.settings.cast=state.characters.map(c=>`${c.name}｜${c.descriptionZh}`).join('\n');}
function castPicker(s){return `<fieldset class="cast-picker"><legend>出场角色 · 可多选同框人物</legend>${state.characters.map(c=>`<label class="cast-chip"><input type="checkbox" name="characterIds" value="${esc(c.id)}" ${(s.characterIds||[]).includes(c.id)?'checked':''}>${esc(c.name)}<small>${esc(c.type)}</small></label>`).join('')||'<small>请先在角色库添加人物。</small>'}</fieldset>`;}
function editShot(id,videoFocus=false){const s=getShot(id);if(!s)return;let manualImage=!!s[lang()==='en'?'promptOverrideEn':'promptOverride'],manualVideo=!!s[lang()==='en'?'videoPromptOverrideEn':'videoPromptOverride'];const negativeKey=lang()==='en'?'negativePromptOverrideEn':'negativePromptOverride';let manualNegative=typeof s[negativeKey]==='string';const imageKey=lang()==='en'?'promptOverrideEn':'promptOverride',videoKey=lang()==='en'?'videoPromptOverrideEn':'videoPromptOverride';showModal(`镜头 ${number(s)} / ${videoFocus?'视频提示词':'分镜编辑'}`,`<form id="shot-form">${s.isIntro?'<p class="field-help">通用片头固定在本集最前面，编辑与状态跟踪方式与其他镜头相同。</p>':`<div class="edit-row"><label>所属集<select name="episodeId">${state.episodes.map(ep=>`<option value="${esc(ep.id)}" ${ep.id===s.episodeId?'selected':''}>${esc(ep.name)}</option>`).join('')}</select></label><label>所属场景<select name="sceneId"></select></label></div>`}<div class="edit-row"><label>空间<select name="spaceId"><option value="">沿用场景空间</option>${state.spaces.map(p=>`<option value="${esc(p.id)}" ${s.spaceId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>画幅<select name="ratio"><option value="">项目默认 · ${esc(state.settings.ratio)}</option>${opts(['9:16','16:9',...(s.ratio==='1:1'?['1:1']:[])],s.ratio)}</select></label></div>${castPicker(s)}<div class="edit-row four">${select('景别','size',SIZES,s.size)}${select('机位','angle',ANGLES,s.angle)}${select('运镜','movement',MOVEMENTS,s.movement)}${input('时长 / 秒','duration',s.duration,'type="number" min="1" max="300" step="any" required')}</div>${area('画面描述 · 中文','visual',s.visual,3,'required')}${area('画面描述 · English','visualEn',s.visualEn||'',2)}<div class="prompt-edit-label"><label>画面瞬间</label><button type="button" class="text-button" id="refine-frame">${icon('spark')} AI 精修</button></div>${area('这一帧可见的动作、表情与姿态','frameMoment',s.frameMoment||'',3,'placeholder="如：林夏右手握着收拢的雨伞，抬眼看向柜台，嘴唇微张，眉梢轻轻扬起"')}${area('Frozen frame · English','frameMomentEn',s.frameMomentEn||'',2)}<div class="edit-row">${input('构图','composition',s.composition||'','placeholder="如：双人过肩构图"')}${input('Composition · English','compositionEn',s.compositionEn||'')}</div><div id="character-position-fields">${positionFields(s.characterIds||[],s.characterPositions||{},s.characterPositionsEn||{})}</div><div class="edit-row">${area('可见环境与物件','environment',s.environment||'',2,'placeholder="如：柜台上摊着旧信封，玻璃橱窗覆着雨滴"')}${area('Visible environment · English','environmentEn',s.environmentEn||'',2)}</div><div class="edit-row lens-row">${select('焦段 / 景深 · 焦段','focalLength',FOCAL_LENGTHS,s.focalLength||'50mm')}${select('焦段 / 景深 · 景深','depthOfField',DEPTHS,s.depthOfField||'浅景深')}</div>${area('对白 / 旁白','dialogue',s.dialogue,2)}<div class="edit-row">${area('后期叠加 · 气泡 / 日志 / 字幕卡','overlay',s.overlay,2)}${area('音效 / 音乐','sound',s.sound,2)}</div><p class="field-help">后期叠加、对白及参考图说明只显示在提示条中，不进入提示词正文。</p><details class="edit-details"><summary>对应剧本原文</summary><blockquote>${esc(s.source||'手动新增镜头，暂无对应原文')}</blockquote></details>${input('创作备注','notes',s.notes)}<div class="form-section"><h3>视频动作与表演</h3>${area('起始画面','videoStart',s.videoStart||'',2)}${area('人物动作过程','videoAction',s.videoAction||'',3)}${input('表情变化','expression',s.expression||'')}${area('结束画面','videoEnd',s.videoEnd||'',2)}<details class="edit-details" ${lang()==='en'?'open':''}><summary>英文动作、表情与起止画面</summary>${area('Start frame','videoStartEn',s.videoStartEn||'',2)}${area('Action sequence','videoActionEn',s.videoActionEn||'',2)}${input('Expression change','expressionEn',s.expressionEn||'')}${area('End frame','videoEndEn',s.videoEndEn||'',2)}</details></div><div class="prompt-edit-label"><label for="image-prompt-edit">生图提示词 · ${lang()==='en'?'English':'中文'}</label><button type="button" class="text-button" id="reset-image">恢复自动提示词</button></div><textarea id="image-prompt-edit" rows="6">${esc(imagePrompt(s))}</textarea><div id="image-prompt-advice">${promptAdvice(s)}</div><div class="negative-editor"><label>负面提示词<textarea id="negative-prompt-edit" rows="3">${esc(negativePrompt(s))}</textarea></label><div class="group-actions"><button type="button" class="text-button" id="copy-negative-draft">复制负面提示词</button><button type="button" class="text-button" id="reset-negative-draft">恢复项目默认</button></div></div><div class="prompt-edit-label"><label for="video-prompt-edit">视频提示词 · ${lang()==='en'?'English':'中文'}</label><button type="button" class="text-button" id="reset-video">恢复自动提示词</button></div><p class="field-help" id="prompt-hint"></p><textarea id="video-prompt-edit" rows="8">${esc(videoPrompt(s))}</textarea>${videoAdvice(s)}<div class="edit-utilities"><div>${s.isIntro?'':`<button type="button" class="button tiny" id="shot-up">${icon('up')} 上移</button><button type="button" class="button tiny" id="shot-down">${icon('down')} 下移</button><button type="button" class="button tiny" id="shot-duplicate">${icon('copy')} 复制镜头</button>`}</div><button type="button" class="text-button danger" data-action="delete" data-id="${esc(s.id)}">${icon('trash')} 删除</button></div><div class="modal-footer">${select('状态','status',STATUSES,s.status)}<button type="button" class="button" id="copy-draft">${icon('copy')} 复制${videoFocus?'视频':'生图'}提示词</button><button class="button primary">保存分镜 ${icon('check')}</button></div></form>`,'edit-modal');
 const form=document.querySelector('#shot-form'),im=document.querySelector('#image-prompt-edit'),vi=document.querySelector('#video-prompt-edit'),negative=document.querySelector('#negative-prompt-edit');
 if(!s.isIntro){const fillScenes=()=>{form.elements.sceneId.innerHTML=state.scenes.filter(sc=>sc.episodeId===form.elements.episodeId.value).map(sc=>`<option value="${esc(sc.id)}" ${s.sceneId===sc.id?'selected':''}>${esc(sc.number)} · ${esc(sc.name)}</option>`).join('');};fillScenes();form.elements.episodeId.onchange=fillScenes;}
 const draft=()=>{const data=new FormData(form),d=Object.fromEntries(data),sc=getScene(d.sceneId||s.sceneId);const ids=data.getAll('characterIds'),characterPositions={...s.characterPositions},characterPositionsEn={...s.characterPositionsEn};for(const [key,value]of data){if(key.startsWith('position:'))characterPositions[key.slice(9)]=value.trim();if(key.startsWith('positionEn:'))characterPositionsEn[key.slice(11)]=value.trim();}return {...s,...d,characterIds:ids,characterPositions,characterPositionsEn,characters:ids.map(id=>state.characters.find(c=>c.id===id)?.name).filter(Boolean).join('、'),duration:Number(d.duration),scene:sc?sc.name:s.scene,sceneNumber:sc?.number||s.sceneNumber,done:d.status==='已确认'};};
 const refresh=()=>{const d=draft();if(!manualImage)im.value=promptFor({...d,[imageKey]:''},ctx(),lang());if(!manualVideo)vi.value=videoPromptFor({...d,[videoKey]:''},ctx(),lang());if(!manualNegative)negative.value=negativePromptFor({...d,[negativeKey]:null},ctx(),lang());document.querySelector('#image-prompt-advice').innerHTML=promptAdvice(d);document.querySelector('#prompt-hint').textContent=`生图：${manualImage?'手工改写':'自动模板'} · 视频：${manualVideo?'手工改写':'自动模板'}。手工内容会保留；点击恢复自动提示词可应用新版生成逻辑。`;};
 form.addEventListener('input',e=>{if(e.target===im)manualImage=true;if(e.target===vi)manualVideo=true;if(e.target===negative)manualNegative=true;refresh();});form.addEventListener('change',e=>{if(e.target.name==='characterIds'){const d=draft();document.querySelector('#character-position-fields').innerHTML=positionFields(d.characterIds,d.characterPositions,d.characterPositionsEn);}refresh();});document.querySelector('#reset-image').onclick=()=>{manualImage=false;refresh();};document.querySelector('#reset-video').onclick=()=>{manualVideo=false;refresh();};
 const capture=()=>{if(!form.reportValidity())return false;const d=draft();if(!s.isIntro&&!d.sceneId){toast('请先在该集创建场景');return false;}Object.assign(s,d,{[imageKey]:manualImage?im.value:'',[videoKey]:manualVideo?vi.value:'',[negativeKey]:manualNegative?negative.value:null});return true;};
 form.onsubmit=e=>{e.preventDefault();snapshot();if(!capture())return;modal.close();commit('分镜已保存');};document.querySelector('#copy-draft').onclick=()=>copy(videoFocus?vi.value:im.value);document.querySelector('#copy-negative-draft').onclick=()=>copy(negative.value,'负面提示词已复制');document.querySelector('#reset-negative-draft').onclick=()=>{manualNegative=false;refresh();};document.querySelector('#refine-frame').onclick=()=>{snapshot();if(!capture())return;save();showAI(id);};
 if(!s.isIntro){document.querySelector('#shot-up').onclick=()=>move(-1);document.querySelector('#shot-down').onclick=()=>move(1);function move(delta){snapshot();if(!capture())return;const peers=state.shots.filter(x=>x.sceneId===s.sceneId),i=peers.indexOf(s);if(!peers[i+delta])return;const a=state.shots.indexOf(s),b=state.shots.indexOf(peers[i+delta]);[state.shots[a],state.shots[b]]=[state.shots[b],state.shots[a]];modal.close();commit('镜头顺序已更新');editShot(id,videoFocus);}document.querySelector('#shot-duplicate').onclick=()=>{snapshot();if(!capture())return;const clone=structuredClone(s);clone.id=uid();clone.status='待生成';clone.done=false;state.shots.splice(state.shots.indexOf(s)+1,0,clone);modal.close();commit('已复制镜头');editShot(clone.id);};}
 refresh();if(videoFocus)document.querySelector('#video-prompt-edit').scrollIntoView({block:'center'});
}
function editSpace(id){const old=state.spaces.find(p=>p.id===id),space=old||{id:uid(),name:'',descriptionZh:'',descriptionEn:''};showModal(old?'编辑空间预设':'自定义空间',`<form id="space-form">${input('空间名称','name',space.name,'required maxlength="50"')}${area('色彩与光线 · 中文','descriptionZh',space.descriptionZh,4)}${area('Color & lighting · English','descriptionEn',space.descriptionEn,4)}<div class="modal-footer">${old?'<button type="button" class="text-button danger" id="delete-space">删除空间</button>':''}<button class="button primary">保存预设</button></div></form>`);document.querySelector('#space-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(!d.name.trim())return;if(state.spaces.some(s=>s.id!==space.id&&s.name===d.name.trim())){toast('空间名称已存在');return;}snapshot();Object.assign(space,{name:d.name.trim(),descriptionZh:d.descriptionZh.trim(),descriptionEn:d.descriptionEn.trim()});if(!old)state.spaces.push(space);modal.close();commit('空间预设已保存');};if(old)document.querySelector('#delete-space').onclick=()=>{if(state.spaces.length===1){toast('至少保留一个空间');return;}confirmAction('删除此空间？','使用它的镜头和场景会改用第一个可用空间。',()=>{snapshot();state.spaces=state.spaces.filter(p=>p.id!==id);for(const s of [...state.scenes,...shots()])if(s.spaceId===id)s.spaceId=state.spaces[0].id;commit('空间已删除');});};}
function baseShot(extra={}){return {id:uid(),episodeId:'',sceneId:'',scene:'',sceneNumber:'',spaceId:'',characterIds:[],characters:'',ratio:'',visual:'请填写镜头中的人物、动作与环境。',visualEn:'',frameMoment:'',frameMomentEn:'',composition:'',environment:'',focalLength:'50mm',depthOfField:'浅景深',characterPositions:{},characterPositionsEn:{},negativePromptOverride:null,negativePromptOverrideEn:null,dialogue:'',size:'中景',angle:'平视',movement:'固定镜头',duration:4,source:'',notes:'',overlay:'',sound:'',status:'待生成',done:false,videoStart:'',videoAction:'',videoEnd:'',expression:'',promptOverride:'',videoPromptOverride:'',...extra};}
function editEpisode(id){const old=getEpisode(id),ep=old||{id:uid(),name:`第${String(state.episodes.length+1).padStart(2,'0')}集`,intro:null};showModal(old?'集设置与通用片头':'新增集',`<form id="episode-form">${input('集名称','name',ep.name,'required maxlength="100"')}<label class="checkbox"><input type="checkbox" name="introEnabled" ${ep.intro?'checked':''}> 启用本集通用片头</label>${area('片头画面描述','introVisual',ep.intro?.visual||'',3)}${input('片头时长 / 秒','introDuration',ep.intro?.duration||5,'type="number" min="1" max="300" step="any" required')}<p class="field-help">片头固定在本集最前面，计入镜头数与时长。保存后可在片头卡片中编辑角色、运镜和提示词。</p><div class="edit-utilities"><div>${old?'<button type="button" class="button tiny" id="episode-up">上移本集</button><button type="button" class="button tiny" id="episode-down">下移本集</button>':''}</div>${old?'<button type="button" class="text-button danger" id="delete-episode">删除本集</button>':''}</div><div class="modal-footer"><button type="button" class="button" data-action="close">取消</button><button class="button primary">保存集设置</button></div></form>`);const form=document.querySelector('#episode-form');const capture=()=>{if(!form.reportValidity())return false;const d=Object.fromEntries(new FormData(form));if(!d.name.trim())return false;ep.name=d.name.trim();ep.intro=d.introEnabled?baseShot({...ep.intro,id:ep.intro?.id||uid(),episodeId:ep.id,isIntro:true,scene:'通用片头',visual:d.introVisual.trim()||'本集通用片头画面',duration:Number(d.introDuration)}):null;if(!old)state.episodes.push(ep);return true;};form.onsubmit=e=>{e.preventDefault();snapshot();if(!capture())return;modal.close();commit('集设置已保存');};if(old){for(const [key,delta]of[['episode-up',-1],['episode-down',1]])document.querySelector('#'+key).onclick=()=>{snapshot();if(!capture())return;const i=state.episodes.indexOf(ep);if(state.episodes[i+delta])[state.episodes[i],state.episodes[i+delta]]=[state.episodes[i+delta],ep];modal.close();commit('集顺序已更新');};document.querySelector('#delete-episode').onclick=()=>confirmAction('删除本集及其全部分镜？','本集的场景、镜头和片头都会删除，可用“撤销”恢复。',()=>{snapshot();state.episodes=state.episodes.filter(e=>e.id!==id);state.scenes=state.scenes.filter(s=>s.episodeId!==id);state.shots=state.shots.filter(s=>s.episodeId!==id);resetFilters();commit('本集已删除');});}}
function editScene(id,episodeId){if(!state.episodes.length){editEpisode();return;}const old=getScene(id),sc=old||{id:uid(),episodeId:episodeId||state.episodes[0].id,number:String(state.scenes.length+1).padStart(2,'0'),name:'',spaceId:state.spaces[0]?.id};showModal(old?'编辑场景':'新增场景',`<form id="scene-form"><label>所属集<select name="episodeId">${state.episodes.map(e=>`<option value="${esc(e.id)}" ${e.id===sc.episodeId?'selected':''}>${esc(e.name)}</option>`).join('')}</select></label><div class="edit-row">${input('场景号','number',sc.number,'required maxlength="50"')}${input('场景名','name',sc.name,'required maxlength="150"')}</div><label>默认空间<select name="spaceId">${state.spaces.map(p=>`<option value="${esc(p.id)}" ${p.id===sc.spaceId?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><div class="edit-utilities"><div>${old?'<button type="button" class="button tiny" id="scene-up">上移本场</button><button type="button" class="button tiny" id="scene-down">下移本场</button>':''}</div>${old?'<button type="button" class="text-button danger" id="delete-scene">删除本场</button>':''}</div><div class="modal-footer"><button type="button" class="button" data-action="close">取消</button><button class="button primary">保存场景</button></div></form>`);const form=document.querySelector('#scene-form');const capture=()=>{if(!form.reportValidity())return false;const d=Object.fromEntries(new FormData(form));snapshot();Object.assign(sc,{episodeId:d.episodeId,name:d.name.trim(),number:d.number.trim(),spaceId:d.spaceId});if(!old)state.scenes.push(sc);for(const s of state.shots.filter(s=>s.sceneId===sc.id))Object.assign(s,{episodeId:sc.episodeId,scene:sc.name,sceneNumber:sc.number});return true;};form.onsubmit=e=>{e.preventDefault();if(!capture())return;modal.close();commit('场景已保存');};if(old){for(const [key,delta]of[['scene-up',-1],['scene-down',1]])document.querySelector('#'+key).onclick=()=>{if(!capture())return;const peers=state.scenes.filter(s=>s.episodeId===sc.episodeId),i=peers.indexOf(sc),target=peers[i+delta];if(target){const a=state.scenes.indexOf(sc),b=state.scenes.indexOf(target);[state.scenes[a],state.scenes[b]]=[target,sc];}modal.close();commit('场景顺序已更新');};document.querySelector('#delete-scene').onclick=()=>confirmAction('删除本场及其镜头？','本场全部镜头会删除，可用“撤销”恢复。',()=>{snapshot();state.scenes=state.scenes.filter(s=>s.id!==id);state.shots=state.shots.filter(s=>s.sceneId!==id);resetFilters();commit('场景已删除');});}}

function generate(){if(!state.script.trim()){toast('请先粘贴或导入剧本');return;}const run=()=>{snapshot();syncNames();state=migrateProject({...state,episodes:[],scenes:[],shots:parseScript(state.script,state.settings),isDemo:false});resetFilters();commit(`已拆分 ${state.shots.length} 个镜头，请逐镜确认`);};if(state.shots.length)confirmAction('重新拆分剧本？','当前分镜与集场设置会替换为新的初稿，建议先导出备份。可撤销恢复。',run);else run();}
function exportModal(){showModal('把分镜带到下一步',`<p class="modal-intro">${shots().length} 个镜头，包含各集片头。导出完整项目，不受当前筛选影响。</p><div class="export-options">${[['export-video','TXT','视频提示词合集','按集、场景与镜号整理'],['export-csv','CSV','分镜表格 · Excel / WPS','含所需全部字段与中英文提示词'],['export-md','MD','分镜文档','画面、对白、声音、原文和提示词'],['export-json','JSON','完整项目备份','含角色图片、视觉设定、集数与场景，可恢复继续编辑']].map(([a,f,t,p])=>`<button data-action="${a}"><span class="file-icon">${f}</span><div><b>${t}</b><p>${p}</p></div>${icon('download')}</button>`).join('')}</div><div class="modal-footer"><button class="text-button" data-action="backup-import">${icon('upload')} 恢复项目备份</button><button class="button" data-action="data-import">${icon('upload')} 导入 JSON / CSV</button><button class="button" data-action="copy-all">复制生图提示词</button><button class="button" data-action="copy-all-video">复制视频提示词</button></div>${loadError?'<button class="button full" data-action="export-raw">导出保留的原始存档</button>':''}`);}
const batch=(ss,kind='both')=>ss.map(s=>kind==='image'?imagePrompt(s):kind==='video'?videoPrompt(s):imagePrompt(s)+'\n\n'+videoPrompt(s)).join('\n\n--------------------\n\n');
function showAI(id){
 const scoped=id?[getShot(id)].filter(Boolean):shots();activeRefinementIds=scoped.map(s=>s.id);
 if(!scoped.length){toast('先生成或新增分镜，再精修画面瞬间');return;}
 showModal('AI 精修 · 一个可以画出来的瞬间',`<p class="modal-intro">把画面描述改写为一帧可见的动作、表情和姿态。精修只回填“画面瞬间”，不会替换原描述、对白或分镜结构。</p><div class="ai-steps"><div><span>01</span><b>复制精修指令到 AI 对话工具</b><p>去掉声音、心理活动和时间过程，把“风铃轻响”“认出了她”“渐渐”“第一次”等转为可见细节。</p><button class="button primary" data-action="copy-ai">${icon('copy')} 复制 AI 精修指令</button></div><div><span>02</span><b>粘贴 AI 返回的 JSON</b><p>按镜头 ID 对应结果，读取后在下方预览并修改。</p></div></div><textarea id="ai-json" rows="6" aria-label="AI 画面瞬间结果" placeholder='[{"id":"镜头ID","frameMoment":"手握伞柄，嘴唇微张，视线朝向柜台","frameMomentEn":"Visible pose and expression"}]'></textarea><button class="button" data-action="import-ai">读取精修结果</button><p class="ai-refine-note">沿用原有的复制指令、粘贴结果方式，本页不直接调用语言模型。下方也可以手动填写。</p><form id="moment-refinement-form"><div class="moment-refinement-list">${scoped.map(s=>`<div class="moment-refinement-row"><b>镜头 ${number(s)}</b><p class="muted">原描述：${esc(s.visual)}</p>${s.dialogue?`<p class="field-help">对白背景：${esc(s.dialogue)}</p>`:''}${area('画面瞬间','moment:'+s.id,s.frameMoment||'',3)}${area('Frozen frame · English','momentEn:'+s.id,s.frameMomentEn||'',2)}</div>`).join('')}</div><div class="modal-footer"><button type="button" class="button" data-action="close">取消</button><button class="button primary">应用画面瞬间</button></div></form>`,'edit-modal');
 document.querySelector('#moment-refinement-form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target),updates=[];for(const id of activeRefinementIds){const s=getShot(id);if(!s)continue;const moment=String(data.get('moment:'+id)||'').trim(),momentEn=String(data.get('momentEn:'+id)||'').trim();if(moment||momentEn)updates.push({s,moment,momentEn});}if(!updates.length){toast('先填写或读取至少一条画面瞬间');return;}snapshot();for(const {s,moment,momentEn}of updates){s.frameMoment=moment;s.frameMomentEn=momentEn;}modal.close();commit(`已更新 ${updates.length} 个画面瞬间`);};
}
function previewMomentResults(value){
 const rows=Array.isArray(value)?value:value?.shots;if(!Array.isArray(rows)||!rows.length)throw new Error('请粘贴包含 id 和 frameMoment 的 JSON 数组');
 const seen=new Set(),validated=[];
 for(const row of rows){if(!row||typeof row.id!=='string'||!activeRefinementIds.includes(row.id))throw new Error('结果包含不在当前精修范围内的镜头 ID');if(seen.has(row.id))throw new Error('结果中有重复的镜头 ID');if(typeof row.frameMoment!=='string'||!row.frameMoment.trim()||row.frameMoment.length>10000)throw new Error('每条结果都需要有效的 frameMoment');if(row.frameMomentEn!==undefined&&typeof row.frameMomentEn!=='string')throw new Error('frameMomentEn 应为英文文本');seen.add(row.id);validated.push(row);}
 const form=document.querySelector('#moment-refinement-form');if(!form)throw new Error('请重新打开 AI 精修窗口');
 for(const row of validated){form.elements.namedItem('moment:'+row.id).value=row.frameMoment.trim();if(typeof row.frameMomentEn==='string')form.elements.namedItem('momentEn:'+row.id).value=row.frameMomentEn.trim();}toast(`已读取 ${validated.length} 条精修结果，请预览后应用`);
}

const readJSON=text=>JSON.parse(text.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,''));
function importData(data,full=false){let next;if(full){if(typeof data.title!=='string'||!Array.isArray(data.shots))throw new Error('请选择完整项目 JSON 备份');next=migrateProject(data);}else if(Array.isArray(data))next=migrateProject({...state,episodes:[],scenes:[],shots:data,isDemo:false});else if(data.settings&&Array.isArray(data.shots))next=migrateProject(data);else if(Array.isArray(data.shots))next=migrateProject({...state,episodes:[],scenes:[],shots:data.shots,isDemo:false});else throw new Error('JSON 应为镜头数组或项目备份');confirmAction('导入并替换当前项目内容？',`将导入 ${orderedShots(next).length} 个镜头。完整备份会同时恢复角色、参考图、项目设置与集场结构。可用“撤销”恢复。`,()=>{snapshot();loadError='';state=next;resetFilters();modal.close();commit('导入完成');});}
function chooseFile(mode){fileMode=mode;const f=document.querySelector('#file-input');f.accept=mode==='script'?'.docx,.doc,.txt,.md,application/vnd.openxmlformats-officedocument.wordprocessingml.document,application/msword,text/plain':mode==='backup'?'.json,application/json':'.json,.csv,application/json,text/csv';f.click();}
function help(){showModal('从剧本到视频的创作流程',`<div class="help-steps"><div><span>01</span><h3>剧本与项目设置</h3><p>直接导入 Word（.docx）、TXT / MD，或粘贴剧本。旧版 .doc 请先用 Word / WPS 另存为 .docx；图片扫描件需先识别文字。用“第01集”“场景01｜地点”标注结构。设置默认画幅、画风前缀、排除元素和空间光线。</p></div><div><span>02</span><h3>建立角色库</h3><p>填写中英文外观、代表色并上传定妆照。AI 角色可多选参考主人。在镜头中勾选全部同框人物。</p></div><div><span>03</span><h3>拆分、组织与精修</h3><p>本地规则按原文拆分初稿，需人工确认节奏。镜头按集、场景组织，可折叠、拖动手柄或用上移下移排序。每集可设置通用片头。AI 精修专门把描述转为一个可画的瞬间；粘贴返回的 JSON 后，只回填画面瞬间。</p></div><div><span>04</span><h3>生成与跟踪</h3><p>复制生图正文，并按下方提示条上传参考图。排除元素用独立按钮复制。对白镜头的黄色提醒表示还需要补充画面瞬间。图生视频请先用生图结果作为首帧，再复制独立的视频动作、表情、运镜和时长提示词。后期叠加内容单独制作。英文版使用对应英文字段；填写完整后效果更准确。用四种状态跟踪进度。</p></div><div><span>05</span><h3>保存、交换与导出</h3><p>数据保存在当前浏览器。JSON 备份含角色图与所有设置，CSV 可在 Excel 打开并重新导入。定期导出备份，分享网址不会同步你的项目。工具整理提示词，不直接生成图片或视频。</p></div></div>`);}

document.addEventListener('click',e=>{
 const p=e.target.closest('[data-panel]');if(p){panel=p.dataset.panel;render();return;}const v=e.target.closest('[data-view]');if(v){view=v.dataset.view;render();return;}const l=e.target.closest('[data-language]');if(l){state.settings.promptLanguage=l.dataset.language;commit('');return;}const ratio=e.target.closest('[data-ratio]');if(ratio){snapshot();state.settings.ratio=ratio.dataset.ratio;commit('');return;}const f=e.target.closest('[data-filter-status]');if(f){statusFilter=f.dataset.filterStatus;render();return;}
 const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id,s=getShot(id);
 switch(a){case 'close':modal.close();break;case 'help':help();break;case 'generate':generate();break;case 'export':exportModal();break;case 'file':chooseFile('script');break;case 'data-import':case 'ai-file':chooseFile('data');break;case 'backup-import':chooseFile('backup');break;case 'ai':showAI(id);break;case 'copy-ai':copy(aiInstruction(state,shots().filter(s=>activeRefinementIds.includes(s.id))));break;
 case 'import-ai':try{previewMomentResults(readJSON(document.querySelector('#ai-json').value));}catch(err){toast('精修结果格式有误：'+err.message);}break;
 case 'edit':editShot(id);break;case 'edit-video':editShot(id,true);break;case 'copy-prompt':if(s)copy(imagePrompt(s),'生图提示词已复制');break;case 'copy-negative':if(s)copy(negativePrompt(s),'负面提示词已复制');break;case 'reset-negative':if(s){snapshot();s[lang()==='en'?'negativePromptOverrideEn':'negativePromptOverride']=null;commit('已恢复项目默认负面提示词');}break;case 'copy-video':if(s)copy(videoPrompt(s),'视频提示词已复制');break;case 'copy-all':copy(batch(shots(),'image'));break;case 'copy-all-video':copy(batch(shots(),'video'));break;case 'copy-scene':copy(batch(state.shots.filter(s=>s.sceneId===id)),'本场生图与视频提示词已复制');break;
 case 'export-video':download(filename()+'_视频提示词.txt',toVideoText(state));break;case 'export-csv':download(filename()+'_分镜表.csv',toCSV(state),'text/csv;charset=utf-8');break;case 'export-md':download(filename()+'_分镜.md',toMarkdown(state),'text/markdown;charset=utf-8');break;case 'export-json':download(filename()+'_项目备份.json',JSON.stringify(exportProject(state),null,2),'application/json');break;case 'export-raw':download(filename()+'_原始存档.json',localStorage.getItem(KEY)||'{}','application/json');break;
 case 'sample':confirmAction('载入示例项目？','当前项目将替换为示例，可用“撤销”恢复。',()=>{snapshot();loadError='';state=starter();resetFilters();commit('已载入示例');});break;
 case 'undo':if(history){const old=JSON.parse(history);history=null;state=migrateProject(old);loadError='';resetFilters();modal.close();commit('已撤销上次操作');}break;
 case 'clear-filters':resetFilters();render();break;
 case 'collapse':collapsed.has(b.dataset.key)?collapsed.delete(b.dataset.key):collapsed.add(b.dataset.key);renderBoard();break;
 case 'filter-episode':resetFilters();episodeFilter=id;panel='episodes';render();break;case 'filter-scene':resetFilters();filter=id;episodeFilter=getScene(id)?.episodeId||'all';panel='episodes';render();break;
 case 'add-character':editCharacter();break;case 'edit-character':editCharacter(id);break;case 'delete-character':confirmAction('删除此角色？','此角色会从镜头选角及其他角色的参考主人中移除；剧本原文与画面描述会保留。',()=>{snapshot();state.characters=state.characters.filter(c=>c.id!==id);for(const c of state.characters)c.referenceOwnerIds=c.referenceOwnerIds.filter(x=>x!==id);for(const shot of shots())shot.characterIds=(shot.characterIds||[]).filter(x=>x!==id);syncNames();commit('角色已删除');});break;
 case 'add-space':editSpace();break;case 'edit-space':editSpace(id);break;case 'add-episode':editEpisode();break;case 'edit-episode':editEpisode(id);break;case 'add-scene':editScene(undefined,b.dataset.episode);break;case 'edit-scene':editScene(id);break;
 case 'confirm':if(s){snapshot();s.done=!s.done;s.status=s.done?'已确认':'待生成';commit('');}break;
 case 'add':{let sc=getScene(b.dataset.scene)||(filter!=='all'?getScene(filter):null)||state.scenes.filter(sc=>episodeFilter==='all'||sc.episodeId===episodeFilter).at(-1);if(!sc){editScene(undefined,episodeFilter!=='all'?episodeFilter:undefined);return;}snapshot();const fresh=baseShot({episodeId:sc.episodeId,sceneId:sc.id,scene:sc.name,sceneNumber:sc.number});state.shots.push(fresh);commit('');editShot(fresh.id);break;}
 case 'delete':if(s)confirmAction('删除这个镜头？','删除后可用“撤销”恢复。',()=>{snapshot();if(s.isIntro)getEpisode(s.episodeId).intro=null;else state.shots=state.shots.filter(x=>x.id!==id);commit('镜头已删除');});break;
 }
});
app.addEventListener('input',e=>{const el=e.target;if(el.id==='script-input'){state.script=el.value;state.isDemo=false;document.querySelector('#char-count').textContent=el.value.length.toLocaleString()+' 字符';save();}if(el.id==='search'){query=el.value;renderBoard();}if(el.dataset.negativeFor){const s=getShot(el.dataset.negativeFor);if(s){s[el.dataset.negativeLanguage==='en'?'negativePromptOverrideEn':'negativePromptOverride']=el.value;save();}}if(el.dataset.project){state.title=el.value;save();}if(el.dataset.setting&&el.tagName==='TEXTAREA'){state.settings[el.dataset.setting]=el.value;if(el.dataset.setting==='stylePrefix')state.settings.style='自定义';save();renderBoard();}});
app.addEventListener('change',e=>{const el=e.target;if(el.dataset.setting){snapshot();state.settings[el.dataset.setting]=el.value;if(el.dataset.setting==='style'){const presets={'电影写实':['电影写实摄影，细腻真实的皮肤和材质，电影画面质感','Cinematic photorealism, natural skin and material detail, film-like image quality'],'日系动画':['日系动画风格，精致线稿，赛璐璐上色','Japanese anime, detailed linework, cel shading'],'国风绘本':['国风绘本插画，细腻笔触，层次丰富','Chinese illustrated storybook, delicate brushwork, layered colors']};if(presets[el.value])[state.settings.stylePrefix,state.settings.stylePrefixEn]=presets[el.value];}commit('');}if(el.dataset.project){state.title=el.value.trim()||'未命名项目';commit('');}if(el.id==='episode-filter'){episodeFilter=el.value;renderBoard();}if(el.id==='scene-filter'){filter=el.value;renderBoard();}if(el.id==='status-filter'){statusFilter=el.value;renderBoard();}if(el.dataset.shotStatus){const s=getShot(el.dataset.shotStatus);if(s){snapshot();s.status=el.value;s.done=s.status==='已确认';commit('');}}});
let importSequence=0;
function previewScriptImport(result){
 const limit=100000;
 showModal('预览导入的剧本',`<p class="modal-intro">${esc(result.title)} · ${esc(result.format)} · ${result.text.length.toLocaleString()} 字符</p><p class="field-help">确认后仅替换剧本文本，现有分镜会保留。检查内容后，点击“拆分为分镜”更新镜头。</p><textarea id="script-import-preview" class="copy-fallback" rows="12" aria-label="导入剧本预览" readonly>${esc(result.text.slice(0,limit))}</textarea>${result.text.length>limit?'<p class="field-help">此处仅预览前 10 万字符，导入时保留完整文字。</p>':''}<div class="modal-footer"><button class="button" data-action="close">取消</button><button class="button primary" id="confirm-script-import">确认导入剧本</button></div>`,'edit-modal');
 document.querySelector('#confirm-script-import').onclick=()=>{snapshot();state.script=result.text;state.title=result.title;state.isDemo=false;panel='script';modal.close();commit('剧本已导入，请检查后拆分为分镜');};
}
document.querySelector('#file-input').addEventListener('change',async e=>{
 const file=e.target.files[0];e.target.value='';if(!file)return;
 const sequence=++importSequence,mode=fileMode;
 if(file.size>25*1024*1024){toast('文件超过 25 MB，请拆分后导入');return;}
 try{
  if(mode==='script'){
   toast(/\.docx$/i.test(file.name)?'正在读取 Word 剧本…':'正在读取剧本…');
   const result=await readScriptFile(file);if(sequence!==importSequence)return;previewScriptImport(result);
  }else{
   const text=(await file.text()).replace(/^\uFEFF/,'');if(sequence!==importSequence)return;
   importData(/\.csv$/i.test(file.name)?parseCSV(text):readJSON(text),mode==='backup');
  }
 }catch(err){if(sequence===importSequence)toast('导入失败：'+err.message);}
});

app.addEventListener('dragstart',e=>{const el=e.target.closest('[data-drag]');if(!el)return;drag={kind:el.dataset.drag,id:el.dataset.id};e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',JSON.stringify(drag));el.classList.add('dragging');});
app.addEventListener('dragover',e=>{const el=e.target.closest('[data-drop]');if(drag&&el){e.preventDefault();e.dataTransfer.dropEffect='move';app.querySelectorAll('.drag-over').forEach(n=>n.classList.remove('drag-over'));el.classList.add('drag-over');}});
app.addEventListener('dragend',()=>{drag=null;app.querySelectorAll('.drag-over,.dragging').forEach(n=>n.classList.remove('drag-over','dragging'));});
function finishDrop(target){if(!drag||!target)return;const {kind,id}=drag,tKind=target.dataset.drop,tId=target.dataset.id;drag=null;app.querySelectorAll('.drag-over,.dragging').forEach(n=>n.classList.remove('drag-over','dragging'));if(id===tId)return;snapshot();const insertBefore=(list,item,target)=>{list.splice(list.indexOf(item),1);list.splice(list.indexOf(target),0,item);};if(kind==='episode'&&tKind==='episode'){insertBefore(state.episodes,getEpisode(id),getEpisode(tId));}else if(kind==='scene'&&(tKind==='scene'||tKind==='episode')){const sc=getScene(id),dest=tKind==='scene'?getScene(tId):null;sc.episodeId=dest?.episodeId||tId;if(dest)insertBefore(state.scenes,sc,dest);else{state.scenes.splice(state.scenes.indexOf(sc),1);state.scenes.push(sc);}for(const s of state.shots.filter(s=>s.sceneId===id))s.episodeId=sc.episodeId;}else if(kind==='shot'&&(tKind==='shot'||tKind==='scene')){const s=getShot(id),dest=tKind==='shot'?getShot(tId):null;if(dest?.isIntro){toast('片头固定在本集最前面');return;}const sc=getScene(dest?.sceneId||tId);if(!sc)return;Object.assign(s,{sceneId:sc.id,episodeId:sc.episodeId,scene:sc.name,sceneNumber:sc.number});if(dest)insertBefore(state.shots,s,dest);else{state.shots.splice(state.shots.indexOf(s),1);state.shots.push(s);}}else return;commit('顺序已更新');}
app.addEventListener('drop',e=>{const target=e.target.closest('[data-drop]');if(drag&&target){e.preventDefault();finishDrop(target);}});
let pointerDrag=null;
app.addEventListener('pointerdown',e=>{const h=e.target.closest('[data-drag]');if(!h||e.button!==0)return;e.preventDefault();pointerDrag={handle:h,kind:h.dataset.drag,id:h.dataset.id,x:e.clientX,y:e.clientY,pointerId:e.pointerId};h.setPointerCapture(e.pointerId);});
app.addEventListener('pointermove',e=>{if(!pointerDrag||e.pointerId!==pointerDrag.pointerId)return;if(!drag&&Math.hypot(e.clientX-pointerDrag.x,e.clientY-pointerDrag.y)<5)return;drag={kind:pointerDrag.kind,id:pointerDrag.id};pointerDrag.handle.classList.add('dragging');app.querySelectorAll('.drag-over').forEach(n=>n.classList.remove('drag-over'));const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-drop]');if(target)target.classList.add('drag-over');});
app.addEventListener('pointerup',e=>{if(!pointerDrag||e.pointerId!==pointerDrag.pointerId)return;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-drop]');pointerDrag.handle.releasePointerCapture(e.pointerId);pointerDrag=null;if(drag&&target)finishDrop(target);drag=null;app.querySelectorAll('.drag-over,.dragging').forEach(n=>n.classList.remove('drag-over','dragging'));});
app.addEventListener('pointercancel',()=>{pointerDrag=null;drag=null;app.querySelectorAll('.drag-over,.dragging').forEach(n=>n.classList.remove('drag-over','dragging'));});

modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
render();
